int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port,
                           struct br_ip *group) {
    int ret = 0;

    spin_lock(&br->multicast_lock);
    if (!netif_running(br->dev)) {
        ret = -EINVAL;
        goto unlock;
    }

    if (port && !port->flags) {
        ret = -EINVAL;
        goto unlock;
    }

    struct br_multicast_entry *entry = kmalloc(sizeof(*entry), GFP_KERNEL);
    if (!entry) {
        ret = -ENOMEM;
        goto unlock;
    }

    memcpy(&entry->group, group, sizeof(*group));
    entry->port = port;
    entry->timer = jiffies + br->multicast_membership_interval;

    if (!port) {
        list_add(&entry->list, &br->multicast_list);
    } else {
        struct br_multicast_port_group *pg = kmalloc(sizeof(*pg), GFP_KERNEL);
        if (!pg) {
            ret = -ENOMEM;
            kfree(entry);
            goto unlock;
        }

        pg->group = *group;
        pg->timer = jiffies + port->multicast_query_interval;
        list_add(&pg->list, &port->multicast_list);
        entry->pg = pg;
    }

unlock:
    spin_unlock(&br->multicast_lock);
    return ret;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int err = 0;
    struct net_bridge_mcast *mcast;
    struct net_bridge_port_mcast *p_mcast;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev)) {
        spin_unlock(&br->multicast_lock);
        return -ENODEV;
    }

    if (port && !port->multicast) {
        spin_unlock(&br->multicast_lock);
        return -EINVAL;
    }

    mcast = kzalloc(sizeof(*mcast), GFP_ATOMIC);
    if (!mcast) {
        spin_unlock(&br->multicast_lock);
        return -ENOMEM;
    }

    *br_ip_get_addr(mcast) = *group;

    if (!port) {
        hlist_add_head(&mcast->hlist, &br->multicast_list);
    } else {
        p_mcast = kzalloc(sizeof(*p_mcast), GFP_ATOMIC);
        if (!p_mcast) {
            kfree(mcast);
            spin_unlock(&br->multicast_lock);
            return -ENOMEM;
        }

        p_mcast->group = *group;
        hlist_add_head(&p_mcast->hlist, &port->multicast_list);
    }

    mcast->timer.data = (unsigned long)mcast;
    mcast->timer.function = br_multicast_timer;
    mod_timer(&mcast->timer, jiffies + br_multicast_membership_interval);

    spin_unlock(&br->multicast_lock);
    return 0;
}

